-- 응원하기와 Shop의 실물 상품. 도서 판본·감상 콘텐츠와 분리한다.
-- 2026-10-09에 확인하고 공식 제휴 링크를 발급한 한국어 56상품을 이관한다.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.commerce_products (
  id bigint generated always as identity primary key,
  collection text not null check (collection in ('support', 'shop')),
  locale text not null check (locale in ('ko', 'en')),
  kind text not null check (btrim(kind) <> ''),
  name text not null check (btrim(name) <> ''),
  size_label text not null,
  description text,
  pair_key text,
  product_url text not null check (product_url ~ '^https://'),
  image_url text not null check (image_url ~ '^https://'),
  affiliate_url text not null check (affiliate_url ~ '^https://'),
  price numeric(12, 2) not null check (price > 0),
  currency text not null check (currency in ('KRW', 'USD')),
  checked_at date not null,
  delivery text not null check (delivery in ('rocket', 'rocketFresh', 'sellerRocket', 'rocketWow', 'standard')),
  review_count integer not null check (review_count >= 0),
  rating numeric(2, 1) check (rating between 0 and 5),
  monthly_purchase_count integer check (monthly_purchase_count >= 0),
  price_condition text check (price_condition = 'coupon'),
  sort_order integer not null default 0 check (sort_order >= 0),
  is_active boolean not null default true,
  unique (collection, locale, product_url)
);

create index commerce_products_listing_idx
  on public.commerce_products(collection, locale, sort_order, id) where is_active;

alter table public.commerce_products enable row level security;
create policy "Published commerce products are public"
  on public.commerce_products for select to anon, authenticated using (is_active);
revoke all on public.commerce_products from public, anon, authenticated;
grant select on public.commerce_products to anon, authenticated;
grant select, insert, update, delete on public.commerce_products to service_role;
grant usage, select on sequence public.commerce_products_id_seq to service_role;

